def jl(p):
    return [json.loads(l) for l in open(p)] if os.path.exists(p) else []


def sha(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for ch in iter(lambda: f.read(1 << 20), b""):
            h.update(ch)
    return h.hexdigest()


def closed_form_ops(m, n, k):
    """exact source-schedule operation counts of the frozen kernel (identical arithmetic in the repaired kernel): initialization + Gray tree updates +
    per-configuration body + final lane reductions (top-bit NY: L/2 lanes per state = L adds per bit)."""
    K = 1 << n; L = 1 << k; P = 1
    while P < n + 1:
        P <<= 1
    d = P.bit_length() - 1
    return L * (2 * m + 1) * (P - 1) + (K - L) * (2 * m + 1) * d + K * (6 * m + 1), K * (3 * m + 1 + n - k) + L * (1 + 2 * m + 2 * (n - k) + k)


def replace_once(text, old, new, label):
    n = text.count(old); assert n == 1, "passage for %s found %d times" % (label, n); return text.replace(old, new)


